// Cloudflare Worker entry (wrangler `main`): the OpenNext build of the Next.js
// app, plus the Cron Trigger handler in ./handlers.ts, wrapped in Sentry.

import * as Sentry from "@sentry/cloudflare";
import { WorkerEntrypoint } from "cloudflare:workers";

// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so it is
// missing before a build (ts-expect-error would then fail after one).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNextWorker from "../.open-next/worker.js";
import {
  DATA_COLLECTION,
  ERROR_SAMPLE_RATE,
  IGNORE_ERRORS,
  scrubEvent,
  TRACES_SAMPLE_RATE,
} from "../src/lib/error-reporting";
import { sendDueReminders } from "../src/server/reminders/send-reminders";
import { forEdge } from "./edge-cache";
import { createWorker, type FetchHandler } from "./handlers";

/**
 * The pages and files Cloudflare's cache sits in front of (wrangler.jsonc "exports"): a
 * hit is answered without running this code. The default entrypoint sends only
 * cacheable requests here (worker/edge-cache.ts).
 */
export class CachedPages extends WorkerEntrypoint<CloudflareEnv> {
  async fetch(request: Request): Promise<Response> {
    const app = openNextWorker as FetchHandler;
    return forEdge(request, await app.fetch(request, this.env, this.ctx));
  }
}

// Error reporting runs only when the SENTRY_DSN secret is set (`wrangler secret put
// SENTRY_DSN`); without it Sentry stays disabled and sends nothing.
export default Sentry.withSentry(
  (env: CloudflareEnv) => {
    const dsn = (env as CloudflareEnv & { SENTRY_DSN?: string }).SENTRY_DSN;
    return {
      dsn: dsn || undefined,
      enabled: Boolean(dsn),
      environment: env.APP_ENV ?? "production",
      sampleRate: ERROR_SAMPLE_RATE,
      tracesSampleRate: TRACES_SAMPLE_RATE,
      dataCollection: DATA_COLLECTION,
      ignoreErrors: IGNORE_ERRORS,
      beforeSend: (event) => scrubEvent(event),
      traceLifecycle: "static",
      beforeSendTransaction: (event) => scrubEvent(event),
    };
  },
  createWorker(openNextWorker as FetchHandler, sendDueReminders),
);
